    for line in lines:
        heading = parse_heading(line)
        if heading is None:
            continue
        title = heading["title"].strip()
        if not title:
            continue
        level = heading["level"]
        node = {"title": title, "level": level, "children": []}
        while stack and stack[-1]["level"] >= level:
            stack.pop()
        if stack:
            stack[-1]["children"].append(node)
        else:
            outline.append(node)
        stack.append(node)
    return outline

